import os, glob, subprocess, pathlib, json, textwrap
files=[]
for root in ['/tmp/in','/tmp/out']:
    for path, dirs, fs in os.walk(root):
        for f in fs:
            p=os.path.join(path,f)
            if any(s in f.lower() for s in ['sig','addr','crash']) or not f.endswith('.cov'):
                try: st=os.stat(p)
                except: continue
                files.append((p,st.st_size))
print(len(files))
for p,s in files[:200]: print(s,p)
